def P(id, title, url, needle, *a, **k):
    if id in QOVR:
        k.setdefault("quote", QOVR[id])
    if id == "ENUM":
        url = M("language.enumerations.overview")
    return _P(id, title, url, OVR.get(id, needle), *a, **k)


def fn(names, cap="@match"):
    return f'((function_call_expression function: (name) {cap}) (#match? {cap} "(?i)^({names})$"))'


def fn_arg(names, arg_node):
    return f'((function_call_expression function: (name) @f arguments: (arguments . (argument {arg_node}))) @match (#match? @f "(?i)^({names})$"))'


def rem(id, title, ver, page, needle, query, bad, good, msg, sev="critical", **kw):
    P(id, title, M(page), needle, query, bad, good, msg, sev=sev, kind="removal", cat="removal", applies=kw.pop("applies", None) or {"php": f">={ver}"},
      doc=f"Migrating to PHP {ver}", docv=f"PHP {ver}", **kw)


def dep(id, title, ver, page, needle, query, bad, good, msg, sev="major", **kw):
    P(id, title, M(page), needle, query, bad, good, msg, sev=sev, kind="deprecation", cat="deprecation", applies=kw.pop("applies", None) or {"php": f">={ver}"},
      doc=f"Deprecated features in PHP {ver}", docv=f"PHP {ver}", **kw)


