SUPER = "\\\\$_(GET|POST|REQUEST|COOKIE|FILES|SERVER)"
sec("UNSERIALIZE-INPUT", "unserialize() on untrusted data", "function.unserialize", "Do not pass untrusted user input to unserialize()",
    fn("unserialize"), T + "$o = unserialize($_COOKIE['cart']);\n", T + "$o = json_decode($_COOKIE['cart'], true, 512, JSON_THROW_ON_ERROR);\n",
    "unserialize() can instantiate arbitrary classes (object injection); use JSON or allowed_classes => false.", mode="ai-confirm",
    ai="Can the serialized data be influenced by a user (cookie, request, DB value written from input) and is allowed_classes not restricted?",
    filters=[r"parent.lacks_re:allowed_classes"])
