    '((function_call_expression function: (name) @m arguments: (arguments (argument [(binary_expression) (encapsed_string (variable_name))] @match))) (#match? @m "(?i)^(mysqli_query|mysqli_real_query|mysqli_multi_query|pg_query|sqlite_query)$"))',
